// Cold-store alarm: relay on D10 follows the probe on A1.
// Three high samples in a row raise it, a clearly low sample clears it.

const int PROBE_PIN = A1;
const int ALARM_PIN = 10;
const float RAISE_C = 12.0;
const float CLEAR_C = 8.0;
const int RUN_NEEDED = 3;
const unsigned long SAMPLE_MS = 20;
const unsigned long REPORT_MS = 500;
const unsigned long ALARM_DELAY_MS = 300;

float lastC = 0.0;
int highRun = 0;
bool alarmOn = false;
unsigned long lastSample = 0;
unsigned long lastReport = 0;
unsigned long lastAlarmTime = 0;

float readCelsius()
{
    int raw = analogRead(PROBE_PIN);
    return (raw * 5000.0 / 1023.0 - 500.0) / 10.0;
}

void setAlarm(bool on)
{
    alarmOn = on;
    digitalWrite(ALARM_PIN, on ? HIGH : LOW);
}

void evaluate(float c)
{
    lastC = c;
    if (c >= RAISE_C)
    {
        if (highRun < RUN_NEEDED)
        {
            highRun++;
        }
        if (highRun >= RUN_NEEDED && !alarmOn && (millis() - lastAlarmTime >= ALARM_DELAY_MS))
        {
            setAlarm(true);
            lastAlarmTime = millis();
        }
    }
    else if (c <= CLEAR_C)
    {
        highRun = 0;
        if (alarmOn && (millis() - lastAlarmTime >= ALARM_DELAY_MS))
        {
            setAlarm(false);
        }
    }
}

void report()
{
    Serial.print("cold ");
    Serial.print(lastC, 1);
    Serial.print(" C alarm=");
    Serial.println(alarmOn ? 1 : 0);
}

void setup()
{
    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);
    Serial.begin(9600);
    lastC = readCelsius();
    lastSample = millis();
    lastReport = millis();
}

void loop()
{
    unsigned long now = millis();
    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        evaluate(readCelsius());
    }
    if (now - lastReport >= REPORT_MS)
    {
        lastReport = now;
        report();
    }
}

// Doorbell chime: a settled press sounds the chime for 300 ms.
// Chime driver on D7, doorbell button on D4 (pull-up), status over UART.

const int CHIME_PIN = 7;
const int BUTTON_PIN = 4;
const unsigned long CHIME_MS = 300;
const unsigned long REPORT_MS = 1000;
const int POLL_MS = 30;
const int CONFIRM_SAMPLES = 2;
const unsigned long DEBOUNCE_MS = 50;

int lowSamples = 0;
bool armed = true;
bool chiming = false;
unsigned long chimeStart = 0;
unsigned long lastReport = 0;
unsigned int rings = 0;
unsigned long lastButtonPressTime = 0;

void startChime()
{
    chiming = true;
    chimeStart = millis();
    rings++;
    digitalWrite(CHIME_PIN, HIGH);
}

void endChime()
{
    chiming = false;
    digitalWrite(CHIME_PIN, LOW);
}

void pollButton()
{
    if (digitalRead(BUTTON_PIN) == LOW)
    {
        if (lowSamples < CONFIRM_SAMPLES)
        {
            lowSamples++;
        }
        if (lowSamples == CONFIRM_SAMPLES && armed)
        {
            armed = false;
            if (!chiming)
            {
                startChime();
            }
        }
    }
    else
    {
        lowSamples = 0;
        armed = true;
    }
}

void report()
{
    Serial.print("chime n=");
    Serial.println(rings);
}

void setup()
{
    pinMode(CHIME_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(CHIME_PIN, LOW);
    Serial.begin(9600);
    lastReport = millis();
}

void loop()
{
    unsigned long currentMillis = millis();
    pollButton();
    if (chiming && currentMillis - chimeStart >= CHIME_MS)
    {
        endChime();
    }
    if (currentMillis - lastReport >= REPORT_MS)
    {
        lastReport = currentMillis;
        report();
    }
    delay(POLL_MS);
}

// Grain bin gauge: running average of the level probe on A3.
// High-level lamp on D5, level report over UART.

const int PROBE_PIN = A3;
const int LAMP_PIN = 5;
const int WINDOW = 32;
const long HIGH_MM = 4300;
const unsigned long SAMPLE_MS = 30;
const unsigned long REPORT_MS = 1000;

int readings[WINDOW];
int slot = 0;
int total = 0;
unsigned long lastSample = 0;
unsigned long lastReport = 0;

void takeSample()
{
    int raw = analogRead(PROBE_PIN);
    total -= readings[slot];
    readings[slot] = raw;
    total += raw;
    slot = (slot + 1) % WINDOW;
}

long averageMm()
{
    return ((long)total * 1000L) / (1023L * WINDOW);
}

void showLamp()
{
    digitalWrite(LAMP_PIN, averageMm() >= HIGH_MM ? HIGH : LOW);
}

void report()
{
    Serial.print("bin ");
    Serial.print(averageMm());
    Serial.println(" mm");
}

void setup()
{
    pinMode(LAMP_PIN, OUTPUT);
    digitalWrite(LAMP_PIN, LOW);
    Serial.begin(9600);
    for (int i = 0; i < WINDOW; i++)
    {
        readings[i] = 0;
    }
    for (int i = 0; i < WINDOW; i++)
    {
        takeSample();
    }
    lastSample = millis();
    lastReport = millis();
    showLamp();
}

void loop()
{
    unsigned long now = millis();
    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        takeSample();
    }
    if (now - lastReport >= REPORT_MS)
    {
        lastReport = now;
        report();
        showLamp();
    }
}

// Lift call panel: buzzer acknowledges a press, a status line shows the
// panel is alive. Buzzer on D11, call button on D5 (pull-up).

const int BUZZER_PIN = 11;
const int BUTTON_PIN = 5;
const unsigned long BUZZ_MS = 300;
const unsigned long SETTLE_MS = 15;
const unsigned long DEBOUNCE_MS = 10;
const unsigned long BEAT_MS = 500;

int rawLevel = HIGH;
bool held = false;
bool buzzing = false;
unsigned long rawChangedAt = 0;
unsigned long lastBeat = 0;
unsigned int beats = 0;

void acknowledge()
{
    buzzing = true;
    digitalWrite(BUZZER_PIN, HIGH);
    delay(BUZZ_MS);
    digitalWrite(BUZZER_PIN, LOW);
    buzzing = false;
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !buzzing)
        {
            acknowledge();
        }
        held = down;
    }
}

void heartbeat()
{
    beats++;
    Serial.print("alive ");
    Serial.println(beats);
}

void setup()
{
    pinMode(BUZZER_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(BUZZER_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastBeat = millis();
}

void loop()
{
    scanButton();
    if (millis() - lastBeat >= BEAT_MS)
    {
        lastBeat = millis();
        heartbeat();
    }
}

